<template>
  <AdminLayout><main class="mx-auto max-w-7xl space-y-6" :aria-labelledby="titleId">
    <AdminPageHeader :eyebrow="eyebrow" :title="title" :description="description" :title-id="titleId"><template #action><button type="button" class="primary-action" :disabled="loading || processing" @click="openModal()"><i class="pi pi-plus mr-2" aria-hidden="true"></i>Nueva {{ singular }}</button></template></AdminPageHeader>
    <section class="grid gap-3 sm:grid-cols-2" :aria-label="`Resumen de ${title}`"><article class="metric"><span>Total de {{ title.toLowerCase() }}</span><strong>{{ total }}</strong><small>Resultado global del listado</small></article><article class="metric"><span>Productos relacionados</span><strong>{{ relatedTotal }}</strong><small>Suma de esta página</small></article></section>
    <form class="filter-panel" :aria-label="`Filtros de ${title}`" @submit.prevent="load(1)"><div class="grid gap-3 sm:grid-cols-[minmax(0,1fr)_auto]"><label class="label">Buscar <div class="relative mt-1"><i class="pi pi-search absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" aria-hidden="true"></i><input v-model.trim="search" class="field pl-10" :placeholder="`Buscar ${singular.toLowerCase()} por nombre`" autocomplete="off"></div></label><div class="flex flex-wrap items-end gap-2"><button class="primary-action" :disabled="loading" type="submit"><i class="pi pi-filter mr-2" aria-hidden="true"></i>Aplicar</button><button class="secondary-action" :disabled="loading" type="button" @click="clear"><i class="pi pi-times mr-2" aria-hidden="true"></i>Limpiar</button><button class="icon-control" :disabled="loading" type="button" aria-label="Actualizar listado" data-tooltip="Actualizar" @click="load(page)"><i class="pi pi-refresh" :class="{ 'pi-spin': loading }" aria-hidden="true"></i></button></div></div></form>
    <section v-if="loadError" class="rounded-2xl border border-red-200 bg-red-50 p-5 text-red-900" role="alert"><p class="font-bold"><i class="pi pi-exclamation-circle mr-2" aria-hidden="true"></i>No se pudo cargar el listado</p><p class="mt-1 text-sm">{{ loadError }}</p><button type="button" class="mt-3 secondary-action" @click="load(page)">Reintentar</button></section>
    <section v-else class="overflow-hidden rounded-2xl bg-white shadow-sm"><div class="overflow-x-auto"><table class="w-full min-w-[660px] text-left text-sm"><thead class="bg-slate-100 text-xs font-bold uppercase tracking-wide text-slate-600"><tr><th scope="col" class="p-4">{{ singular }}</th><th scope="col" class="p-4 text-center">Productos</th><th scope="col" class="p-4 text-center">Estado</th><th scope="col" class="p-4 text-right">Acciones</th></tr></thead><tbody><template v-if="loading"><tr v-for="row in 5" :key="row" class="border-t"><td v-for="cell in 4" :key="cell" class="p-4"><div class="h-5 animate-pulse rounded bg-slate-200" :class="cell === 1 ? 'w-48' : 'mx-auto w-20'"></div></td></tr></template><template v-else-if="items.length"><tr v-for="item in items" :key="item.id" class="border-t border-slate-100 transition hover:bg-slate-50"><td class="p-4"><div class="flex items-center gap-3"><span class="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-blue-50 font-black text-blue-700"><i :class="icon" aria-hidden="true"></i></span><span class="font-semibold text-slate-900">{{ item.name }}</span></div></td><td class="p-4 text-center font-semibold text-slate-700">{{ safeNumber(item.products_count) }}</td><td class="p-4 text-center"><AdminStatusBadge :active="isActive(item)" :active-label="'Activa'" :inactive-label="'Inactiva'" /></td><td class="p-4"><div class="flex justify-end gap-1"><AdminIconButton icon="pi pi-pencil" label="Editar" @click="openModal(item)" /><AdminIconButton :icon="isActive(item) ? 'pi pi-ban' : 'pi pi-check-circle'" :label="isActive(item) ? 'Desactivar' : 'Activar'" :tone="isActive(item) ? 'text-red-700' : 'text-emerald-700'" @click="confirmStatus(item)" /></div></td></tr></template><tr v-else><td colspan="4"><AdminEmptyState :icon="search ? 'pi pi-search' : icon" :title="search ? `No encontramos ${title.toLowerCase()} con esa búsqueda` : `Todavía no hay ${title.toLowerCase()}`" :description="search ? 'Prueba ajustando o limpiando la búsqueda.' : `Crea la primera ${singular.toLowerCase()} desde este panel.`"><button type="button" class="mt-4 primary-action" @click="search ? clear() : openModal()">{{ search ? 'Limpiar búsqueda' : `Nueva ${singular}` }}</button></AdminEmptyState></td></tr></tbody></table></div><AdminPagination :page="page" :last-page="lastPage" :loading="loading" :summary="paginationSummary" @change="load" /></section>
    <div v-if="showModal" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-3" role="dialog" aria-modal="true" :aria-labelledby="modalTitle"><form class="w-full max-w-md rounded-2xl bg-white shadow-2xl" @submit.prevent="save"><header class="flex items-start gap-3 border-b border-slate-100 p-5"><span class="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-100 text-blue-800"><i :class="editing ? 'pi pi-pencil' : 'pi pi-plus'" aria-hidden="true"></i></span><div class="flex-1"><h2 :id="modalTitle" class="text-xl font-black text-slate-900">{{ editing ? `Editar ${singular}` : `Nueva ${singular}` }}</h2><p class="mt-1 text-sm text-slate-600">{{ editing ? 'Actualiza el nombre sin cambiar sus relaciones.' : `Registra una nueva ${singular.toLowerCase()} para el catálogo.` }}</p></div><AdminIconButton icon="pi pi-times" label="Cerrar" @click="closeModal" /></header><div class="p-5"><label class="label">Nombre<input v-model.trim="form.name" class="field mt-1" autofocus required></label><p v-if="errors.name" class="mt-1 text-xs font-semibold text-red-700">{{ errors.name[0] }}</p></div><footer class="flex justify-end gap-3 border-t border-slate-100 p-5"><button type="button" class="secondary-action" :disabled="processing" @click="closeModal">Cancelar</button><button class="primary-action" :disabled="processing">{{ processing ? 'Guardando…' : 'Guardar' }}</button></footer></form></div>
  </main></AdminLayout>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'; import { useConfirm } from 'primevue/useconfirm'; import { useToast } from 'primevue/usetoast'; import AdminLayout from '@/layouts/AdminLayout.vue'; import AdminEmptyState from '@/components/admin/AdminEmptyState.vue'; import AdminIconButton from '@/components/admin/AdminIconButton.vue'; import AdminPageHeader from '@/components/admin/AdminPageHeader.vue'; import AdminPagination from '@/components/admin/AdminPagination.vue'; import AdminStatusBadge from '@/components/admin/AdminStatusBadge.vue'; import api from '@/api';
const props = defineProps({ endpoint:{type:String,required:true},title:{type:String,required:true},singular:{type:String,required:true},eyebrow:{type:String,required:true},description:{type:String,required:true},icon:{type:String,default:'pi pi-tag'} }); const toast=useToast(),confirm=useConfirm(),items=ref([]),search=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),loadError=ref(''),showModal=ref(false),editing=ref(false),processing=ref(false),form=ref({id:null,name:''}),errors=ref({}); const titleId=computed(()=>`${props.singular.toLowerCase()}-title`),modalTitle=computed(()=>`${props.singular.toLowerCase()}-modal-title`),relatedTotal=computed(()=>items.value.reduce((sum,item)=>sum+(Number(item.products_count)||0),0)),paginationSummary=computed(()=>total.value?`${items.value.length} de ${total.value} registros`:'Sin registros para mostrar'); const validId=id=>Number.isInteger(Number(id))&&Number(id)>0; const safeNumber=value=>Math.max(0,Number(value)||0); const isActive=item=>item.is_active!==false&&Number(item.is_active)!==0;
async function load(target=1){if(loading.value)return;loading.value=true;loadError.value='';try{const {data}=await api.get(props.endpoint,{params:{page:target,search:search.value||undefined}});items.value=data.data||[];page.value=Number(data.current_page)||1;lastPage.value=Number(data.last_page)||1;total.value=safeNumber(data.total);}catch(e){loadError.value=e.response?.data?.message||'No se pudo cargar la información.';}finally{loading.value=false;}} function clear(){search.value='';load(1);} function closeModal(){showModal.value=false;editing.value=false;form.value={id:null,name:''};errors.value={};} function openModal(item=null){if(item&&!validId(item.id)){toast.add({severity:'error',summary:'Registro inválido',detail:'No se puede editar este registro.',life:3000});return;}editing.value=!!item;form.value={id:item?.id||null,name:item?.name||''};errors.value={};showModal.value=true;} async function save(){if(processing.value)return;processing.value=true;errors.value={};try{editing.value?await api.put(`${props.endpoint}/${form.value.id}`,{name:form.value.name}):await api.post(props.endpoint,{name:form.value.name});closeModal();toast.add({severity:'success',summary:'Guardado',detail:`${props.singular} guardada correctamente.`,life:2500});await load(page.value);}catch(e){errors.value=e.response?.status===422?e.response.data.errors||{}:{};toast.add({severity:'error',summary:'No se pudo guardar',detail:e.response?.data?.message||e.message,life:3500});}finally{processing.value=false;}} function confirmStatus(item){if(!validId(item?.id))return;const next=!isActive(item);confirm.require({message:`¿Desea ${next?'activar':'desactivar'} ${item.name}?`,header:'Confirmar cambio de estado',icon:'pi pi-exclamation-triangle',acceptLabel:'Confirmar',rejectLabel:'Cancelar',accept:()=>changeStatus(item,next)});} async function changeStatus(item,next){try{await api.patch(`${props.endpoint}/${item.id}/status`,{is_active:next});toast.add({severity:'success',summary:'Estado actualizado',detail:`${props.singular} ${next?'activada':'desactivada'}.`,life:2500});await load(page.value);}catch(e){toast.add({severity:'error',summary:'No se pudo cambiar el estado',detail:e.response?.data?.message||e.message,life:4000});}} onMounted(()=>load());
</script>
<style scoped>.metric{border:1px solid #e2e8f0;border-radius:1rem;background:#fff;padding:1rem;box-shadow:0 1px 2px #0f172a0d}.metric span,.metric small{display:block;color:#64748b;font-size:.8rem;font-weight:600}.metric strong{display:block;margin:.35rem 0;font-size:1.65rem;color:#0f172a}.filter-panel{border-radius:1rem;background:#fff;padding:1rem;box-shadow:0 1px 2px #0f172a0d}.label{display:block;font-size:.875rem;font-weight:700;color:#334155}.field{width:100%;border:1px solid #cbd5e1;border-radius:.65rem;padding:.65rem .8rem;color:#0f172a}.field:focus{outline:2px solid #3b82f6;outline-offset:1px}.primary-action,.secondary-action,.icon-control{min-height:2.5rem;border-radius:.6rem;font-weight:700}.primary-action{background:#2563eb;padding:.55rem .85rem;color:#fff}.secondary-action{border:1px solid #cbd5e1;padding:.55rem .85rem;color:#334155}.icon-control{position:relative;width:2.5rem;border:1px solid #cbd5e1;color:#334155}button:disabled{cursor:not-allowed;opacity:.55}button:focus-visible{outline:2px solid #2563eb;outline-offset:2px}.icon-control::after{content:attr(data-tooltip);position:absolute;z-index:60;bottom:calc(100% + .4rem);left:50%;transform:translateX(-50%);visibility:hidden;border-radius:.35rem;background:#0f172a;padding:.3rem .5rem;color:#fff;font-size:.75rem;opacity:0}.icon-control:hover::after,.icon-control:focus-visible::after{visibility:visible;opacity:1}</style>
